        return pd.DataFrame()

    normalized_data = {}
    for key, value in data.items():
        if isinstance(value, (int, float)):
            normalized_data[key] = float(value * 2)
        elif isinstance(value, list):
            normalized_data[key] = [float(v * 2) if isinstance(v, (int, float)) else v for v in value]
        elif isinstance(value, str):
            match = re.search(r"[-+]?\d*\.\d+|\d+", value)
            if match:
                num = float(match.group())
                normalized_data[key] = str(value).replace(match.group(), str(num * 2))
            else:
                normalized_data[key] = value
        else:
            normalized_data[key] = value

    return pd.DataFrame([normalized_data])
